import{_ as a,o as e,c as d,ak as o}from"./chunks/framework.DKi5cyCJ.js";const b=JSON.parse('{"title":"ADC 驱动","description":"采样时间与源阻抗、规则组与注入组、ENOB、过采样和参考电压","frontmatter":{"title":"ADC 驱动","description":"采样时间与源阻抗、规则组与注入组、ENOB、过采样和参考电压","date":"2026-10-21T00:00:00.000Z"},"headers":[],"relativePath":"pages/blog/2026-10-21-ADC驱动.md","filePath":"pages/blog/2026-10-21-ADC驱动.md"}'),r={name:"pages/blog/2026-10-21-ADC驱动.md"};function s(p,t,l,n,i,c){return e(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="adc-驱动" tabindex="-1">ADC 驱动 <a class="header-anchor" href="#adc-驱动" aria-label="Permalink to &quot;ADC 驱动&quot;">​</a></h1><blockquote><p>系列目录：<a href="/pages/blog/2026-10-20-嵌入式驱动面试手册.html">嵌入式驱动面试手册</a></p></blockquote><p>12 位只是标称分辨率。理想 LSB = Vref / 4096，3.3 V 时约 0.8 mV。有效位数 ENOB = (SINAD − 1.76) / 6.02，一块标称 12 位的 ADC 实际可能只有 10 位左右。参考电压的精度和温漂是天花板，滤波和校准都突破不了。</p><h2 id="采样时间" tabindex="-1">采样时间 <a class="header-anchor" href="#采样时间" aria-label="Permalink to &quot;采样时间&quot;">​</a></h2><p>采样阶段是外部信号通过源阻抗给内部采样电容充电。充到 12 位附近大约要 9 个时间常数：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tsample ≥ 9 × Rs × Cadc</span></span></code></pre></div><p><code>Rs = 10 kΩ</code>、<code>Cadc = 8 pF</code> 时，时间常数 80 ns，采样时间至少约 720 ns。源阻抗越高，采样时间要越长，否则读数偏低。高于大约 10 kΩ 时加运放跟随，比把采样时间拉到极限更稳。</p><p>总转换时间 = 采样时间 + 转换周期（很多系列是 12.5 个 ADC 时钟）。算出来的采样率还要和手册标称上限比较，理论值可以高于芯片允许的最大值。</p><h2 id="规则组与注入组" tabindex="-1">规则组与注入组 <a class="header-anchor" href="#规则组与注入组" aria-label="Permalink to &quot;规则组与注入组&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>规则组</th><th>注入组</th></tr></thead><tbody><tr><td>通道数</td><td>最多 16</td><td>最多 4</td></tr><tr><td>行为</td><td>按 Rank 扫描</td><td>可以打断规则组</td></tr><tr><td>常见用途</td><td>多通道 + DMA</td><td>过流、过压</td></tr></tbody></table><p>多通道扫描加 DMA 循环是日常配置。每个通道的采样时间加起来必须小于触发周期。双缓冲用来避免 CPU 还在算上一批时，DMA 把缓冲区盖掉。</p><h2 id="校准和过采样" tabindex="-1">校准和过采样 <a class="header-anchor" href="#校准和过采样" aria-label="Permalink to &quot;校准和过采样&quot;">​</a></h2><p>上电做一次硬件校准，主要去掉偏移。两点校准再用两个已知电压修正偏移和增益。它们修不了参考电压温漂和前端噪声。</p><p>高精度用外部基准，Vref 脚就近放 100 nF。不要默认“参考就是 VDDA”。</p><p>过采样每增加 4 倍，理论上大约多 1 位，前提是噪声接近白噪声。16 次平均大约 2 位，不是采得越多越好。G0/G4 一类可以在硬件里累加和移位。</p><p><a href="/pages/blog/2026-10-20-嵌入式驱动面试手册.html">返回目录</a></p>',16)])])}const _=a(r,[["render",s]]);export{b as __pageData,_ as default};
